//! sphinx.ext.autodoc's directives (automodule, autoclass, ..., and the generating
//! directives of other domains, such as odin:autoproc) are generated by the host: the
//! reader never reads Python. It hands the directive to the domain's provider
//! (`Config::autodoc`), which answers with reStructuredText as autodoc's documenters
//! write it (".. py:class:: Name(sig)", :module:, the docstring, members), and parses
//! that text where the directive stands, as AutodocDirective parses its generated
//! content. Without a provider the directives are unknown, as in Sphinx without the
//! extension.

use guidedoc::{Arg, Fail, Message, arg_int, arg_span, diagnostic};
use guidedoc_rst::{Directive, OptSpec, OptType, Parser, join_lines, opt};

use crate::domains::find_domain;
use crate::extension::Sphinx;
use crate::messages::AUTODOC_NESTED;
use crate::text::trim_space;

/// One option of an autodoc directive, as written; `value` is "" for a flag.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AutodocOption<'r> {
    /// The option's name ("members").
    pub name: &'r str,
    /// Its value, joined and trimmed.
    pub value: String,
}

/// One autodoc directive and the context it needs: the current module and class (for
/// Python, py:module and py:class; for other domains what their `autodoc_context`
/// gives) and the document.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AutodocRequest<'r> {
    /// The domain whose provider runs ("py", "odin").
    pub domain: &'r str,
    /// The directive's name as its handler names it ("autoclass", "odin:autoproc").
    pub directive: &'r str,
    /// The argument, its lines joined by spaces.
    pub argument: &'r str,
    /// The options as written.
    pub options: Vec<AutodocOption<'r>>,
    /// The content, lines joined with "\n".
    pub content: &'r str,
    /// The current module (package).
    pub module: &'r str,
    /// The current class (type).
    pub class: &'r str,
    /// The document's name.
    pub docname: &'r str,
}

/// A problem the provider found, reported at the directive: a static message (with a
/// hint, Elm style) and its arguments.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AutodocMessage {
    /// The message.
    pub message: Message,
    /// Its `{0}` and `{1}` arguments.
    pub args: [Arg; 2],
}

/// What a provider generated: reStructuredText to parse where the directive stands,
/// named as a source for diagnostics ("<autodoc flask.Flask>"), and its messages.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AutodocResult {
    /// The generated source's name.
    pub name: String,
    /// The generated reStructuredText; empty adds nothing.
    pub text: String,
    /// What to report about it.
    pub messages: Vec<AutodocMessage>,
}

/// The host's generator of a domain's auto directives. It belongs to the caller's trust
/// boundary; it is shared between reads, so it takes `&self`.
pub trait AutodocProvider: Send + Sync {
    /// Generates the text `request` stands for.
    fn generate(&self, request: &AutodocRequest<'_>) -> AutodocResult;
}

/// Every option an autodoc directive may take, as text: autodoc accepts any option and
/// checks it for the object type, which the host does; the no- forms negate
/// autodoc_default_options.
pub(crate) const AUTODOC_OPTIONS: &[OptSpec] = &[
    opt("members", OptType::Text),
    opt("undoc-members", OptType::Text),
    opt("no-index", OptType::Text),
    opt("noindex", OptType::Text),
    opt("no-index-entry", OptType::Text),
    opt("inherited-members", OptType::Text),
    opt("show-inheritance", OptType::Text),
    opt("private-members", OptType::Text),
    opt("special-members", OptType::Text),
    opt("ignore-module-all", OptType::Text),
    opt("exclude-members", OptType::Text),
    opt("member-order", OptType::Text),
    opt("imported-members", OptType::Text),
    opt("class-doc-from", OptType::Text),
    opt("no-value", OptType::Text),
    opt("synopsis", OptType::Text),
    opt("platform", OptType::Text),
    opt("deprecated", OptType::Text),
    opt("annotation", OptType::Text),
    opt("no-members", OptType::Text),
    opt("no-undoc-members", OptType::Text),
    opt("no-inherited-members", OptType::Text),
    opt("no-show-inheritance", OptType::Text),
    opt("no-private-members", OptType::Text),
    opt("no-special-members", OptType::Text),
    opt("no-ignore-module-all", OptType::Text),
    opt("no-exclude-members", OptType::Text),
    opt("no-member-order", OptType::Text),
    opt("no-imported-members", OptType::Text),
    opt("no-class-doc-from", OptType::Text),
    opt("no-no-value", OptType::Text),
    opt("no-no-index", OptType::Text),
    opt("no-no-index-entry", OptType::Text),
];

/// How deeply generated text may generate more.
const MAX_AUTODOC_NESTING: usize = 8;

/// The name the provider of sphinx.ext.inheritance_diagram's `inheritance-diagram`
/// directive is registered under in `Config::autodoc`. It is given the directive as an
/// autodoc directive of the `py` domain and answers with a graph.
pub const INHERITANCE_DIAGRAM: &str = "inheritance-diagram";

/// Runs an autodoc directive of `domain` through its provider.
pub(crate) fn autodoc_directive(
    sx: &Sphinx<'_>,
    p: &mut Parser<'_, '_>,
    d: &Directive<'_>,
    domain: &str,
) -> Result<(), Fail> {
    provided_directive(sx, p, d, domain, domain)
}

/// Runs a directive through the provider registered as `provider`, in the context
/// (current module and class) of `domain`.
pub(crate) fn provided_directive(
    sx: &Sphinx<'_>,
    p: &mut Parser<'_, '_>,
    d: &Directive<'_>,
    provider: &str,
    domain: &str,
) -> Result<(), Fail> {
    let Some(provider) = sx.config.autodoc_for(provider) else {
        let m = guidedoc_rst::messages::DIRECTIVE_UNKNOWN;
        p.report(m, d.name_span, arg_span(d.name_span), Arg::None);
        return Ok(());
    };
    if sx.state().autodoc_depth >= MAX_AUTODOC_NESTING {
        p.report(AUTODOC_NESTED, d.span, arg_int(MAX_AUTODOC_NESTING as i64), Arg::None);
        return Ok(());
    }
    let (module, class) = find_domain(domain)
        .map_or_else(Default::default, |(_, dm)| dm.autodoc_context(&sx.state()));
    let argument = d.argument();
    let content = join_lines(&d.content, "\n");
    let options = d
        .options
        .iter()
        .map(|o| AutodocOption {
            name: o.spec.name,
            value: trim_space(&join_lines(&o.lines, " ")).to_owned(),
        })
        .collect();
    let request = AutodocRequest {
        domain,
        directive: d.handler().map_or(d.name, |h| h.name),
        argument: trim_space(&argument),
        options,
        content: &content,
        module: &module,
        class: &class,
        docname: &sx.config.docname,
    };
    let result = provider.generate(&request);
    for m in result.messages {
        let [a, b] = m.args;
        p.ctx.b.reports().report(diagnostic(m.message, d.span, a, b));
    }
    if result.text.is_empty() {
        return Ok(());
    }
    let Some(id) = p.ctx.add_source(&result.name, &result.text) else { return Ok(()) };
    sx.state().autodoc_depth += 1;
    let parsed = p.parse_source(id, d.sections);
    sx.state().autodoc_depth -= 1;
    parsed
}
